fn solve(n: i8) -> i8 {
    let mut rem = n;
    let mut count = 0;
    // Denominations in descending order
    let denoms: [i8; 5] = [100, 20, 10, 5, 1];

    for &d in &denoms {
        // how many of this denomination
        count += rem / d;
        // update the remainder
        rem %= d;
    }

    count
}

